INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Qual dos seguintes exames de imagem é o mais sensível para detectar pequenas quantidades de líquido pleural (em torno de 5 a 10 mL)?", "options": {"a": "Radiografia de tórax em PA.", "b": "Radiografia de tórax em perfil.", "c": "Ultrassonografia de tórax.", "d": "Radiografia de tórax em decúbito lateral (Laurell).", "e": "Ressonância Magnética torácica."}, "answer": "c", "rationale": "A ultrassonografia de tórax é extremamente sensível, conseguindo detectar volumes mínimos de 5-20 mL de líquido pleural. Para comparação, o RX em perfil precisa de cerca de 75 mL e o RX em PA de pelo menos 175-200 mL para apagar o seio costofrênico.", "option_rationales": {"a": "Incorreta. Pouco sensível para volumes pequenos.", "b": "Incorreta. Melhor que PA, mas ainda exige volume moderado.", "c": "Correta. Padrão-ouro para detecção de pequenos volumes e loculações.", "d": "Incorreta. Detecta volumes a partir de 25-50 mL, mas menos sensível que o US.", "e": "Incorreta. Cara e pouco prática para esta finalidade, apesar de detectar o líquido."}, "difficulty": "media", "tags": ["Pneumologia", "Radiologia", "Ultrassonografia", "Propedêutica"]}'::jsonb, 50, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A decorticação pulmonar por videotoracoscopia ou toracotomia está indicada primariamente em qual fase do empiema pleural?", "options": {"a": "Fase Exsudativa (Líquid fluido, pH normal).", "b": "Fase de Organização (Pulmão encarcerado por carapaça fibrosa sólida).", "c": "Fase Fibrinopurulenta inicial (pH < 7,2, mas sem septos densos).", "d": "Sempre no primeiro dia de internação de qualquer empiema.", "e": "Apenas em pacientes imunocomprometidos."}, "answer": "b", "rationale": "A decorticação é a remoção da ''casca'' de fibrina e tecido fibroso que se forma sobre a pleura visceral na fase de organização (última fase do empiema). É indicada quando a drenagem tubular falha em reexpandir o pulmão devido a esse encarceramento.", "option_rationales": {"a": "Incorreta. Fase inicial, trata-se apenas com dreno ou antibiótico.", "b": "Correta. Indicação clássica de cirurgia para ''soltar'' o pulmão.", "c": "Incorreta. Nesta fase tentam-se fibrinolíticos antes da cirurgia agressiva.", "d": "Incorreta. Conduta exagerada.", "e": "Incorreta. Indicação baseada na fase da pleurite, não no status imune isolado."}, "difficulty": "media", "tags": ["Pneumologia", "Cirurgia Torácica", "Empiema", "Decorticação"]}'::jsonb, 51, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente tabagista crônico apresenta derrame pleural à direita. A análise mostra: pH 7,42, Glicose 90 mg/dL, Proteína 2,8 g/dL (Sérica 6,5 g/dL) e LDH 180 U/L (Sérico 400 U/L). De acordo com os critérios de Light, este derrame é classificado como:", "options": {"a": "Exsudato.", "b": "Transudato.", "c": "Empiema.", "d": "Inconclusivo.", "e": "Líquido Borderline."}, "answer": "b", "rationale": "Cálculo do Light: 1) Prot Pleural/Prot Sérica = 2,8/6,5 = 0,43 (Corte > 0,5); 2) LDH Pleural/LDH Sérico = 180/400 = 0,45 (Corte > 0,6); 3) LDH Pleural = 180 (Corte > 2/3 do limite superior do soro, assumindo 400 como normal, 180 não atinge 266). Como nenhum critério é preenchido, o líquido é um transudato.", "option_rationales": {"a": "Incorreta. Precisaria de pelo menos um critério positivo.", "b": "Correta. Classificação clássica pelos valores apresentados.", "c": "Incorreta. Exige critérios inflamatórios severos.", "d": "Incorreta. Os cálculos são claros.", "e": "Incorreta. Não existe este termo na classificação de Light."}, "difficulty": "facil", "tags": ["Pneumologia", "Líquido Pleural", "Critérios de Light"]}'::jsonb, 52, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "No diagnóstico de Derrame Pleural por Lúpus Eritematoso Sistêmico (Pleurite Lúpica), a dosagem de anticorpos antinucleares (FAN) no líquido pleural apresenta qual utilidade clínica?", "options": {"a": "Baixa utilidade, pois o FAN pleural costuma ser negativo mesmo no lúpus.", "b": "Alta utilidade se o título for > 1:160, sendo muito específico para pleurite lúpica.", "c": "Inútil, pois é sempre idêntico ao título sérico e nunca ajuda no diagnóstico.", "d": "Substitui a necessidade de biópsia renal.", "e": "Indica obrigatoriamente insuficiência renal lúpica associada."}, "answer": "b", "rationale": "Diferentes estudos mostram que a dosagem de FAN no líquido pleural com títulos elevados (especialmente se maiores que os títulos séricos ou > 1:160) tem alto valor diagnóstico para pleurite lúpica. A detecção de células LE no líquido também é altamente específica.", "option_rationales": {"a": "Incorreta. Costuma ser positivo no lúpus serosítico.", "b": "Correta. Títulos altos no líquido favorecem o diagnóstico local de atividade lúpica.", "c": "Incorreta. Pode ajudar na diferenciação diagnóstica em casos de serosite isolada.", "d": "Incorreta. Não substitui avaliação orgânica de outros sistemas.", "e": "Incorreta. A serosite pode ocorrer independente da nefrite."}, "difficulty": "dificil", "tags": ["Pneumologia", "Reumatologia", "Lúpus", "FAN Pleural"]}'::jsonb, 53, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A causa mais comum de derrame pleural transudativo em pacientes hospitalizados é:", "options": {"a": "Cirrose Hepática.", "b": "Síndrome Nefrótica.", "c": "Insuficiência Cardíaca Congestiva.", "d": "Embolia Pulmonar.", "e": "Hipotireoidismo."}, "answer": "c", "rationale": "A Insuficiência Cardíaca Congestiva (ICC) é disparada a causa mais comum de transudatos pleurais no mundo. Estima-se que mais de 500.000 casos ocorram anualmente apenas nos EUA.", "option_rationales": {"a": "Incorreta. Comum, mas menos que a ICC.", "b": "Incorreta. Causa de transudato, mas menos frequente.", "d": "Incorreta. TEP causa exsudato em 75-80% das vezes e transudato em apenas 20%.", "e": "Incorreta. Causa rara de derrame isolado significativo."}, "difficulty": "facil", "tags": ["Pneumologia", "Epidemiologia", "ICC", "Transudato"]}'::jsonb, 54, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente de 48 anos, etilista, apresenta quadro de dor abdominal em barra e dispneia. RX de tórax mostra derrame pleural à esquerda volumoso. Toracentese evidencia líquido sero-hemorrágico com amilase de 5.000 U/L (Amilase sérica 250 U/L). A tomografia de abdome confirma pseudocisto pancreático. Qual o mecanismo do derrame pleural neste caso?", "options": {"a": "Simpatia pleural à inflamação peripancreática.", "b": "Fístula Pancreato-Pleural através do hiato aórtico ou defeitos diafragmáticos.", "c": "Hipoalbuminemia por má absorção pancreática.", "d": "Translocação bacteriana intestinal para a pleura.", "e": "Metástase pleural de câncer de pâncreas oculto."}, "answer": "b", "rationale": "Em casos de pancreatite crônica com pseudocisto, pode haver a formação de uma fístula que leva o suco pancreático rico em amilase diretamente para o espaço pleural (geralmente o esquerdo). Diferente do derrame da pancreatite aguda (simpático), o derrame da fístula é volumoso, crônico e com níveis de amilase astronômicos.", "option_rationales": {"a": "Incorreta. O derrame simpático não atinge níveis tão altos de amilase (5.000 U/L).", "b": "Correta. Mecanismo de derrames pancreáticos volumosos recorrentes.", "c": "Incorreta. Causaria transudato bilateral.", "d": "Incorreta. Não explica a amilase.", "e": "Incorreta. O pseudocisto e a amilase indicam patologia benigna ductal pancreática."}, "difficulty": "media", "tags": ["Pneumologia", "Gastroenterologia", "Amilase Pleural", "Pancreatite"]}'::jsonb, 55, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "O gradiente de albumina (Soro - Líquido Pleural) é considerado o melhor teste para identificar transudatos cardíacos rotulados como exsudatos pelos critérios de Light. Qual valor de gradiente favorece o diagnóstico de Transudato?", "options": {"a": "< 0,5 g/dL", "b": "> 1,2 g/dL", "c": "> 3,1 g/dL", "d": "= 0", "e": "< 1,2 g/dL"}, "answer": "b", "rationale": "Um gradiente de albumina soro-pleura > 1,2 g/dL tem alta acurácia para identificar transudatos que parecem exsudatos devido ao uso de diuréticos (falsos exsudatos). O valor de 3,1 g/dL é usado para o gradiente de Proteína Total, não Albumina.", "option_rationales": {"a": "Incorreta. Sugere exsudato verdadeiro.", "b": "Correta. Padrão de gradiente para ICC sob tratamento.", "c": "Incorreta. Este é o corte para Proteína Total.", "d": "Incorreta. Fisicamente impossível.", "e": "Incorreta. Favorece exsudato."}, "difficulty": "media", "tags": ["Pneumologia", "Laboratório", "Gradiente de Albumina"]}'::jsonb, 56, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A biópsia pleural por agulha ''cega'' (Abrams) apresenta sensibilidade significativamente maior para o diagnóstico de qual patologia em comparação ao câncer pleural?", "options": {"a": "Mesotelioma.", "b": "Linfoma.", "c": "Tuberculose Pleural.", "d": "Adenocarcinoma metastático.", "e": "Sarcoidose."}, "answer": "c", "rationale": "A TB pleural acomete a pleura de forma difusa (granulomas em toda a superfície), o que dá à biópsia cega uma sensibilidade de 70-80%. Já o câncer pleural costuma acometer a pleura de forma nodular e focal, fazendo com que a biópsia cega ''erre'' o alvo frequentemente (sensibilidade de 40-50%).", "option_rationales": {"a": "Incorreta. Exige biópsia dirigida por VATS pelo baixo rendimento da cega.", "b": "Incorreta. Exige grande quantidade de tecido para arquitetura linfonodal.", "c": "Correta. Principal indicação de biópsia de Abrams/Cope.", "d": "Incorreta. Citologia costuma ser melhor que biópsia cega.", "e": "Incorreta. Rara e de difícil captura na biópsia cega."}, "difficulty": "media", "tags": ["Pneumologia", "Tuberculose", "Biópsia Pleural"]}'::jsonb, 57, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A ''Pleurodese Espontânea'' é um fenômeno que pode ocorrer após a inserção de um cateter pleural de demora (PleurX) em pacientes com derrame neoplásico recorrente. Sobre este fenômeno, assinale a alternativa correta.", "options": {"a": "Ocorre em 100% dos pacientes após 30 dias de uso do cateter.", "b": "A sínfise pleural ocorre pelo contato crônico e inflamação induzida pelo cateter, permitindo sua posterior retirada em cerca de 50% dos casos.", "c": "É um sinal de mau prognóstico, indicando falha renal iminente.", "d": "Ocorre apenas se forem injetados agentes esclerosantes pelo cateter diariamente.", "e": "Impede a reexpansão pulmonar e causa dor intratável."}, "answer": "b", "rationale": "Pacientes com cateter pleural de demora podem desenvolver pleurodese espontânea (autopleurodese) em cerca de 45-50% das vezes. A drenagem constante e a irritação mecânica do cateter favorecem a adesão das pleuras, permitindo retirar o dreno de forma definitiva após a cessação do débito.", "option_rationales": {"a": "Incorreta. Ocorre em aproximadamente metade dos pacientes.", "b": "Correta. Vantagem principal do cateter de demora em relação à pleurodese química única.", "c": "Incorreta. É um desfecho positivo e desejado.", "d": "Incorreta. Ocorre espontaneamente apenas com a drenagem.", "e": "Incorreta. Pelo contrário, o cateter permite a saída controlada do líquido e alívio da dor."}, "difficulty": "dificil", "tags": ["Pneumologia", "Oncologia", "Cateter de Demora", "Pleurodese"]}'::jsonb, 58, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente de 60 anos apresenta derrame pleural bilateral e ascite. A análise do líquido pleural revela: Transudato, Glicose normal, ausência de células malignas. A dosagem de hormônio tireoestimulante (TSH) é de 85 mUI/L. Qual a denominação correta para o derrame pleural neste contexto de hipotireoidismo severo?", "options": {"a": "Efunsão mista trans-exsudativa.", "b": "Derrame Mixedematoso.", "c": "Pseudotumor de Myx (Myxoma pleural).", "d": "Anasarca Endócrina.", "e": "Síndrome de Hoffman."}, "answer": "b", "rationale": "O derrame mixedematoso ocorre no hipotireoidismo severo por aumento da permeabilidade capilar e redução da drenagem linfática. Embora possa ser exsudato em alguns casos raros, é classicamente um transudato que resolve apenas com a reposição hormonal (levotiroxina).", "option_rationales": {"a": "Incorreta. Termo não utilizado.", "b": "Correta. Nome clínico do derrame por mixedema.", "c": "Incorreta. Myxoma é um tumor cardíaco.", "d": "Incorreta. Termo genérico.", "e": "Incorreta. Síndrome de Hoffman é a miopatia do hipotireoidismo no adulto."}, "difficulty": "media", "tags": ["Pneumologia", "Endocrinologia", "Hipotireoidismo", "Mixedema"]}'::jsonb, 59, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente de 45 anos, submetido a cirurgia de revascularização do miocárdio há 3 semanas, retorna ao pronto-socorro com febre (38,2°C), dor torácica pleurítica e dispneia. Ao exame, percebe-se atrito pericárdico à ausculta. Radiografia de tórax revela derrame pleural bilateral e aumento da silhueta cardíaca. A análise do líquido pleural mostra um exsudato hemorrágico com predomínio de linfócitos. Qual o diagnóstico e o tratamento de escolha?", "options": {"a": "Embolia pulmonar pós-operatória; anticoagulação plena.", "b": "Pneumonia nosocomial tardia; piperacilina-tazobactam.", "c": "Síndrome de Post-Pericardiotomia (Síndrome de Dressler); anti-inflamatórios (AINEs) e colchicina.", "d": "Tamponamento cardíaco traumático; pericardiocentese imediata e drenagem pleural.", "e": "Empiema pleural bilateral por contaminação intraoperatória; drenagem tubular bilateral."}, "answer": "c", "rationale": "A Síndrome de Lesão Pós-Cardíaca (que inclui a síndrome pós-pericardiotomia) é um processo autoimune que ocorre de semanas a meses após cirurgias cardíacas, infartos ou traumas. Caracteriza-se por pleuropericardite, febre e derrames exsudativos (muitas vezes hemorrágicos ou eosinofílicos). O tratamento baseia-se em anti-inflamatórios (Aspirina ou Ibuprofeno) e Colchicina para prevenir recorrências.", "option_rationales": {"a": "Incorreta. O quadro de atrito pericárdico e a temporalidade pós-cirúrgica apontam mais para serosite autoimune.", "b": "Incorreta. A febre no pós-operatório tardio associada a serosites é mais comumente autoimune do que pneumonia bacteriana sem infiltrado.", "c": "Correta. Diagnóstico clássico do pós-operatório de CRM.", "d": "Incorreta. O aumento da silhueta sugere derrame, mas não há sinais clínicos de choque obstrutivo (tamponamento).", "e": "Incorreta. Empiema bilateral seria extremamente raro e o líquido seria purulento/neutrofílico, não linfocítico-hemorrágico."}, "difficulty": "media", "tags": ["Pneumologia", "Cardiologia", "Síndrome de Dressler", "Derrame Pleural"]}'::jsonb, 60, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Para o diagnóstico de Chilotórax, a dosagem de triglicerídeos no líquido pleural é o teste inicial de escolha. No entanto, em valores intermediários (entre 50 e 110 mg/dL), qual exame adicional é mandatório para confirmar a presença de quilo no espaço pleural?", "options": {"a": "Dosagem de Colesterol Pleural.", "b": "Pesquisa de Quilomícrons por eletroforese de lipoproteínas.", "c": "Relação Creatinina Pleural / Sérica.", "d": "Contagem de Eosinófilos no líquido.", "e": "Linfocintilografia de membros inferiores."}, "answer": "b", "rationale": "Valores de TG > 110 mg/dL confirmam quilotórax; < 50 mg/dL praticamente excluem. No ''limbo'' entre 50-110 mg/dL, a presença de quilomícrons na eletroforese do líquido pleural é o padrão-ouro para o diagnóstico confirmatório.", "option_rationales": {"a": "Incorreta. O colesterol ajuda no pseudoquilotórax, não na confirmação do quilo verdadeiro borderline.", "b": "Correta. Exame definitivo para casos com TG inconclusivo.", "c": "Incorreta. Usado no urinotórax.", "d": "Incorreta. Não tem relação com o quilo.", "e": "Incorreta. Pode ser usada para localizar a fístula, mas não para o diagnóstico bioquímico inicial do líquido."}, "difficulty": "media", "tags": ["Pneumologia", "Laboratório", "Quilotórax", "Lipídios"]}'::jsonb, 61, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente de 70 anos apresenta derrame pleural volumoso à direita. A análise do líquido revela: Exsudato hemorrágico, com citologia oncótica positiva para adenocarcinoma. A tomografia mostra múltiplas metástases hepáticas e cerebrais. O controle das metástases cerebrais é priorizado, mas o paciente apresenta dispneia importante pelo derrame. Qual o manejo paliativo MAIS ADEQUADO para o derrame pleural neste cenário de doença avançada?", "options": {"a": "Pleurodese com talco via toracotomia.", "b": "Inserção de cateter pleural de demora (IPC) para drenagem domiciliar.", "c": "Toracocenteses de alívio diárias no hospital.", "d": "Radioterapia sobre o hemitórax direito.", "e": "Quimioterapia sistêmica isolada, sem intervenção pleural."}, "answer": "b", "rationale": "O cateter pleural de demora (IPC) é excelente para pacientes com câncer avançado, curta expectativa de vida e sintomas de dispneia recorrente. Ele permite que o paciente seja tratado em casa, reduzindo o tempo de hospitalização e sendo menos invasivo que a pleurodese por drenagem tubular ou cirúrgica.", "option_rationales": {"a": "Incorreta. Muito agressivo e exige internação prolongada.", "b": "Correta. Padrão paliativo moderno para qualidade de vida domiciliar.", "c": "Incorreta. Toracocenteses repetidas causam alto desconforto e risco de infecção.", "d": "Incorreta. Radioterapia não trata o derrame volumoso agudo.", "e": "Incorreta. A quimio demora a agir; o alívio imediato da dispneia exige drenagem."}, "difficulty": "facil", "tags": ["Pneumologia", "Oncologia", "Palhação", "Cateter Pleural"]}'::jsonb, 62, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A maioria dos derrames pleurais associados ao Tromboembolismo Pulmonar (TEP) são pequenos e localizados unilateralmente. Qual a característica citológica e bioquímica MAIS FREQUENTE nesses derrames?", "options": {"a": "Transudato com predominância de células mesoteliais.", "b": "Exsudato tipicamente hemorrágico e frequentemente eosinofílico.", "c": "Empiema purulento por infarto pulmonar infectado.", "d": "Líquido leitoso com triglicerídeos elevados.", "e": "Exsudato com glicose zero (consumida pelo infarto)."}, "answer": "b", "rationale": "No TEP, o derrame ocorre por aumento da permeabilidade capilar após a isquemia e liberação de mediadores inflamatórios. Aproximadamente 75-80% são exsudatos, frequentemente hemorrágicos (pela isquemia/infarto) e eosinofílicos (pela presença de sangue no espaço pleural).", "option_rationales": {"a": "Incorreta. Apenas 20% do TEP cursa com transudato.", "b": "Correta. Perfil clássico do TEP na pleura.", "c": "Incorreta. O infarto pulmonar pode infectar (pneumonia), mas não é o padrão do TEP agudo.", "d": "Incorreta. TEP não causa quilotórax.", "e": "Incorreta. A glicose costuma ser normal no TEP."}, "difficulty": "media", "tags": ["Pneumologia", "TEP", "Derrame Pleural", "Eosinofilia"]}'::jsonb, 63, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Em pacientes com Sarcoidose, o derrame pleural é uma manifestação rara. Quando ocorre, o diagnóstico diferencial mais difícil com base apenas no líquido pleural (exsudato linfocítico) é com:", "options": {"a": "Insuficiência Cardíaca Congestiva.", "b": "Tuberculose Pleural.", "c": "Derrame Parapneumônico Simples.", "d": "Urinotórax.", "e": "Atelectasia de base."}, "answer": "b", "rationale": "Ambas (Sarcoidose e Tuberculose) são doenças granulomatosas que produzem exsudatos linfocíticos. Embora o ADA ajude (muito alto na TB, baixo/médio na Sarcoidose), o perfil citológico pode ser idêntico, exigindo biópsia e cultura para diferenciação definitiva.", "option_rationales": {"a": "Incorreta. ICC dá transudato.", "b": "Correta. Principal desafio diagnóstico pelo perfil inflamatório granulomatoso similar.", "c": "Incorreta. Pneumonia dá líquido neutrofílico.", "d": "Incorreta. Urinotórax é transudato ácido.", "e": "Incorreta. Atelectasia dá transudatos pequenos."}, "difficulty": "media", "tags": ["Pneumologia", "Diagnóstico Diferencial", "Sarcoidose", "Tuberculose"]}'::jsonb, 64, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "O escore RAPID foi validado para prever o prognóstico de pacientes com infecção pleural (Empiema/Derrame Parapneumônico). Quais são as variáveis que compõem este escore?", "options": {"a": "Respiração, Albumina, Plaqueta, Idade, Diabetes.", "b": "Renal (Ureia), Age (Idade), Purulence (Purulência do líquido), Infection source (Hospitalar vs Comunitária), Dietary (Estado Nutricional).", "c": "Renal (Ureia), Age (Idade), Purulence (Purulência), Infection source (Hospitalar vs Comunitária), Dietary (Albumina).", "d": "Raciocínio, Albumina, pH, Idade, Derrame.", "e": "Radiologia, ADA, Proteína, Idade, Densidade."}, "answer": "c", "rationale": "O escore RAPID utiliza: Renal (Ureia sérica), Age (Idade), Purulence (se o líquido é purulento ou não), Infection source (Comunitária vs Nosocomial) e Dietary (Albumina sérica). Ele estratifica o risco de morte em 3 meses.", "option_rationales": {"a": "Incorreta. Plaqueta e Diabetes não fazem parte do RAPID clássico.", "b": "Incorreta. ''Dietary'' não é estado nutricional genérico, mas especificamente a Albumina.", "c": "Correta. Definição correta do acrônimo e das variáveis.", "d": "Incorreta. Raciocínio não é variável clínica objetiva.", "e": "Incorreta. ADA e Densidade não compõem o escore."}, "difficulty": "dificil", "tags": ["Pneumologia", "Infectologia", "Prognóstico", "Escore RAPID"]}'::jsonb, 65, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente de 35 anos apresenta quadro de febre, perda de peso e sudorese noturna há 1 mês. RX de tórax com derrame pleural bilateral e múltiplos nódulos pulmonares de 2-4 mm (padrão miliar). A análise do líquido pleural revela exsudato linfocítico, ADA de 20 U/L. O Teste Rápido Molecular (TRM-TB) no líquido foi negativo. Qual o achado mais provável que explicaria um ADA baixo em um quadro clínico tão sugestivo de Tuberculose?", "options": {"a": "Tuberculose Pleural em paciente imunocompetente.", "b": "Tuberculose Miliar com disseminação pleural secundária em paciente imunodeprimido.", "c": "Linfoma de Hodgkin mimetizando TB.", "d": "Coccidioidomicose pulmonar.", "e": "Adenocarcinoma de pulmão estágio IV."}, "answer": "b", "rationale": "Enquanto a Tuberculose Pleural isolada (por hipersensibilidade tardia) cursa com ADA muito alto, a Tuberculose Miliar que envolve a pleura pode apresentar derrames com ADA baixo ou limítrofe, especialmente em pacientes com HIV ou imunossupressão grave, devido à falha na resposta imune celular exuberante que eleva o ADA.", "option_rationales": {"a": "Incorreta. TB pleural clássica tem ADA > 40 invariavelmente.", "b": "Correta. A forma miliar e o status imune podem ''falsear'' o ADA para baixo.", "c": "Incorreta. Embora possível, o quadro miliar favorece TB.", "d": "Incorreta. Fungos podem dar ADA baixo, mas a TB miliar é a causa clássica de ADA falso-baixo no contexto infeccioso disseminado.", "e": "Incorreta. O padrão miliar é diferente da carcinomatose linfangítica típica."}, "difficulty": "dificil", "tags": ["Pneumologia", "Infectologia", "Tuberculose Miliar", "ADA"]}'::jsonb, 66, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Sobre o Mesotelioma Maligno em relação ao tabagismo, assinale a alternativa correta.", "options": {"a": "O tabagismo é o principal fator de risco para mesotelioma, superando o asbesto.", "b": "O tabagismo não tem relação causal com o mesotelioma; o risco é determinado quase exclusivamente pela exposição ao asbesto.", "c": "O tabagismo e o asbesto agem de forma sinérgica (multiplicativa) no risco de mesotelioma, assim como no câncer de pulmão.", "d": "Apenas o tabagismo passivo é fator de risco para mesotelioma.", "e": "Fumar protege contra o mesotelioma devido à indução de muco protetor."}, "answer": "b", "rationale": "Diferentemente do câncer de pulmão (carcinoma), onde tabaco e asbesto multiplicam o risco, o mesotelioma pleural não tem associação direta com o fumo. O fator determinante é a inalação de fibras de amianto (asbesto) e, em menor escala, radiação ou erionita.", "option_rationales": {"a": "Incorreta. O fumo causa adenocarcinoma e epidermoide, não mesotelioma.", "b": "Correta. Dado importante de epidemiologia para diferenciar das outras neoplasias torácicas.", "c": "Incorreta. A sinergia ocorre apenas para o câncer de pulmão ''comum'', não para o mesotelioma.", "d": "Incorreta. Sem nexo causal estabelecido.", "e": "Incorreta. Afirmativa estapafúrdia."}, "difficulty": "media", "tags": ["Pneumologia", "Epidemiologia", "Mesotelioma", "Tabagismo"]}'::jsonb, 67, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Em qual situação o gradiente de albumina (Soro - Pleura) é superior aos critérios de Light para o diagnóstico da causa do derrame?", "options": {"a": "Suspeita de Tuberculose Pleural.", "b": "Suspeita de Empiema.", "c": "Pacientes com Insuficiência Cardíaca que fizeram uso prévio de diuréticos.", "d": "Pacientes com câncer de pulmão metastático.", "e": "Qualquer derrame bilateral."}, "answer": "c", "rationale": "Os diuréticos removem água do espaço pleural mais rápido que as proteínas, ''concentrando'' o transudato e transformando-o em um exsudato pelos critérios de Light. O gradiente de albumina (> 1,2 mg/dL) ignora essa concentração e identifica corretamente a origem cardíaca.", "option_rationales": {"a": "Incorreta. TB é exsudato verdadeiro; o gradiente será baixo.", "b": "Incorreta. Empiema é exsudato verdadeiro.", "c": "Correta. Indicação clássica para uso de gradiente.", "d": "Incorreta. Câncer é exsudato verdadeiro.", "e": "Incorreta. Nem todo derrame bilateral é cardíaco."}, "difficulty": "facil", "tags": ["Pneumologia", "Laboratório", "ICC", "Critérios de Light"]}'::jsonb, 68, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A biópsia pleural por videotoracoscopia (VATS) é considerada o padrão-ouro para o diagnóstico de derrames pleurais exsudativos de difícil diagnóstico. Qual a sensibilidade aproximada deste procedimento para a detecção de malignidade?", "options": {"a": "60-70%.", "b": "80-85%.", "c": "95-98%.", "d": "Apenas 50%, pois só visualiza a pleura parietal.", "e": "100%, sem possibilidade de erro."}, "answer": "c", "rationale": "A VATS permite a visualização direta de toda a cavidade pleural e a coleta de biópsias dirigidas das áreas mais suspeitas. Sua sensibilidade para malignidade é extremamente alta, aproximando-se de 100%.", "option_rationales": {"a": "Incorreta. Este é o valor da biópsia cega.", "b": "Incorreta. Valor baixo para VATS.", "c": "Correta. Eficácia diagnóstica superior na pleura.", "d": "Incorreta. Visualiza parietal, visceral e diafragma.", "e": "Incorreta. Embora rara, a falha pode ocorrer em casos de aderências totais que impeditam a visualização (espaço pleural sínfise)."}, "difficulty": "media", "tags": ["Pneumologia", "VATS", "Diagnóstico", "Oncologia"]}'::jsonb, 69, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente tabagista pesado desenvolve derrame pleural hemorrágico unilateral. A citologia oncótica e duas biópsias de Abrams foram negativas para malignidade. O paciente apresenta também um nódulo na glândula adrenal direita evidenciado na TC. Qual a conduta diagnóstica mais lógica a seguir?", "options": {"a": "Realizar terceira biópsia de Abrams no mesmo hemitórax.", "b": "Biópsia por agulha guiada por TC da glândula adrenal.", "c": "Tratamento empírico para Tuberculose com esquema RIPE.", "d": "Videotoracoscopia imediata e pleurodese.", "e": "Pet-CT e acompanhamento radiológico em 6 meses."}, "answer": "b", "rationale": "Em casos de suspeita de câncer de pulmão metastático (derrame + nódulo adrenal), a biópsia da metástase presumida (adrenal) é frequentemente mais fácil e fornece tanto o diagnóstico histológico quanto o estadiamento (M1b) simultaneamente, evitando procedimentos torácicos mais invasivos se a adrenal for positiva.", "option_rationales": {"a": "Incorreta. O rendimento marginal seria baixo.", "b": "Correta. Estratégia de ''atirar no alvo mais fácil'' para diagnóstico e estadiamento.", "c": "Incorreta. Sem evidências de TB e com forte suspeita de neoplasia.", "d": "Incorreta. A biópsia da adrenal pode poupar o paciente de uma cirurgia torácica diagnóstica.", "e": "Incorreta. O acompanhamento de 6 meses é perigoso em neoplasias agressivas."}, "difficulty": "dificil", "tags": ["Pneumologia", "Oncologia", "Estadiamento", "Biópsia Adrenal"]}'::jsonb, 70, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A causa mais comum de quilotórax traumático (latrogênico) é a cirurgia torácica. Qual procedimento cirúrgico apresenta o maior risco histórico de lesão do ducto torácico?", "options": {"a": "Pneumonectomia devido a câncer.", "b": "Esofagectomia.", "c": "Revascularização do miocárdio.", "d": "Drenagem de abscesso pulmonar.", "e": "Timectomia por via esternal."}, "answer": "b", "rationale": "Devido à íntima proximidade anatômica entre o esôfago e o ducto torácico no mediastino posterior, as esofagectomias representam a principal causa cirúrgica de quilotórax iatrogênico.", "option_rationales": {"a": "Incorreta. Risco existe, mas menor que na esofagectomia.", "b": "Correta. Causa clássica de lesão do ducto.", "c": "Incorreta. O ducto é posterior e a CRM é anterior/medial.", "d": "Incorreta. Procedimento geralmente periférico.", "e": "Incorreta. Mediastino anterior não hospeda o ducto torácico em seu trajeto principal."}, "difficulty": "media", "tags": ["Pneumologia", "Cirurgia Torácica", "Quilotórax iatrogênico"]}'::jsonb, 71, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "O achado de células de um carcinoma espinocelular no líquido pleural, em comparação ao adenocarcinoma, é:", "options": {"a": "Muito mais comum.", "b": "Inexistente, pois o CEC não causa derrame.", "c": "Muito menos comum (raro), devido ao padrão de crescimento local/obstrutivo do CEC.", "d": "Sempre indicativo de empiema associado.", "e": "O critério diagnóstico para Mesotelioma."}, "answer": "c", "rationale": "O adenocarcinoma é periférico e invade a pleura precocemente, sendo a causa mais comum de derrame neoplásico citológico positivo. O carcinoma espinocelular (CEC) é central e causa mais atelectasias obstrutivas (transudatos por pressão negativa) do que invasão pleural direta (exsudatos), sendo raro encontrar células de CEC na citologia pleural.", "option_rationales": {"a": "Incorreta. O adenocarcinoma domina a citologia pleural.", "b": "Incorreta. Pode causar, mas é infrequente.", "c": "Correta. Diferença importante de comportamento biológico dos tumores de pulmão.", "d": "Incorreta. Sem relação direta.", "e": "Incorreta. Mesotelioma tem origem mesotelial, não escamosa/espinocelular."}, "difficulty": "media", "tags": ["Pneumologia", "Oncologia", "Derrame Neoplásico", "CEC"]}'::jsonb, 72, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente de 80 anos desenvolve derrame pleural volumoso bilateral e anasarca. A análise revela um transudato. O TSH, a função renal e a função hepática são normais. A dosagem de albumina sérica é de 1,8 g/dL (muito baixa). O paciente é desdentado e mora sozinho. Qual o provável diagnóstico nutricional associado ao derrame?", "options": {"a": "Kwashiorkor do idoso (Desnutrição proteica grave).", "b": "Escorbuto por deficiência de vitamina C.", "c": "Beribéri (Deficiência de Tiamina) com ICC de alto débito.", "d": "Síndrome de Má Absorção por doença celíaca tardia.", "e": "Síndrome Paraneoplásica consumptiva."}, "answer": "a", "rationale": "A hipoalbuminemia grave (< 2,0 g/dL) pode levar à formação de transudatos pleurais bilaterais por redução da pressão oncótica plasmática. Em idosos com baixa ingesta proteica (hipoproteinemia), este quadro de anasarca e derrame é uma manifestação de desnutrição proteica severa.", "option_rationales": {"a": "Correta. Causa de transudato por baixa pressão oncótica.", "b": "Incorreta. Escorbuto causa sangramentos e alterações de pele, não derrame pleural por hipoproteinemia isolada.", "c": "Incorreta. O Beribéri causa ICC, o que daria derrame, mas a albumina de 1,8 aponta para causa oncótica primária (nutricional).", "d": "Incorreta. Menos provável no contexto social descrito.", "e": "Incorreta. Neoplasias dariam mais comumente exsudatos e não necessariamente hipoalbuminemia tão isolada e grave sem outros sinais."}, "difficulty": "media", "tags": ["Pneumologia", "Nutrologia", "Geriatria", "Hipoalbuminemia"]}'::jsonb, 73, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Qual dos seguintes parâmetros no líquido pleural ajuda a diferenciar um hemotórax verdadeiro de uma toracentese traumática (acidente de punção)?", "options": {"a": "Presença de leucócitos > 10.000.", "b": "Hematócrito pleural > 50% do hematócrito periférico.", "c": "Ausência de plaquetas no líquido.", "d": "Presença de eosinofilia > 10%.", "e": "LDH pleural < 200 U/L."}, "answer": "b", "rationale": "Um hemotórax é definido por um hematócrito no líquido pleural de pelo menos 50% do hematócrito sanguíneo do paciente. Se o hematócrito pleural for baixo, trata-se apenas de um derrame sero-hemorrágico ou contaminação por sangue durante o procedimento.", "option_rationales": {"a": "Incorreta. Indica infecção.", "b": "Correta. Critério diagnóstico clássico de hemotórax.", "c": "Incorreta. As plaquetas tendem a se agregar e sumir da contagem automática no líquido pleural em ambos os casos.", "d": "Incorreta. Sangue na pleura dá eosinofilia, mas não diferencia a origem aguda.", "e": "Incorreta. Líquidos hemorrágicos têm LDH alto."}, "difficulty": "facil", "tags": ["Pneumologia", "Hemotórax", "Diagnóstico"]}'::jsonb, 74, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A asbestose (fibrose intersticial pelo amianto) se associa ao mesotelioma de qual forma?", "options": {"a": "A asbestose é uma condição obrigatória para que o mesotelioma se desenvolva.", "b": "O mesotelioma pode ocorrer na ausência de asbestose radiológica ou clínica, bastando a exposição prévia às fibras de asbesto.", "c": "Apenas asbestose grave leva ao mesotelioma.", "d": "As duas doenças nunca ocorrem no mesmo paciente.", "e": "O tratamento da asbestose previne o mesotelioma."}, "answer": "b", "rationale": "O mesotelioma e a asbestose são doenças independentes causadas pelo mesmo agente. Um paciente pode ter mesotelioma sem ter fibrose pulmonar (asbestose) e vice-versa. O risco de mesotelioma está ligado à carga de exposição e ao tempo de latência.", "option_rationales": {"a": "Incorreta. São patologias distintas.", "b": "Correta. Dado importante para estadiamento e vigilância ocupacional.", "c": "Incorreta. Não há essa correlação linear direta.", "d": "Incorreta. Podem coexistir frequentemente.", "e": "Incorreta. Não existe tratamento curativo para asbestose que previna a transformação maligna pleural."}, "difficulty": "media", "tags": ["Pneumologia", "Oncologia", "Asbesto", "Asbestose"]}'::jsonb, 75, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente tabagista crônico apresenta derrame pleural volumoso. A toracentese revela líquido âmbar, límpido. Bioquímica: Glicose 95, Proteína 4,2 (Sérica 6,8), LDH 520 (Sérico 300). Citologia: Predomínio de linfócitos (92%), células mesoteliais raras, ausência de células malignas. ADA 25 U/L. Biópsia de Abrams: Inflamação crônica inespecífica. Próximo passo recomendado por diretrizes?", "options": {"a": "Tratamento empírico para Tuberculose.", "b": "Videotoracoscopia (VATS) com biópsias dirigidas.", "c": "Novo ciclo de antibióticos por 14 dias.", "d": "Acompanhamento radiológico em 1 ano.", "e": "Pesquisa de células LE no líquido pleural."}, "answer": "b", "rationale": "O paciente possui um exsudato linfocítico com ADA intermediário e biópsia cega negativa. Em um fumante idoso, a suspeita de câncer é alta e a biópsia de Abrams negativa não exclui a doença. O próximo passo é a biópsia dirigida por VATS.", "option_rationales": {"a": "Incorreta. O ADA é baixo (25) e o paciente é fumante, câncer é prioritário.", "b": "Correta. Conduta padrão para exsudatos linfocíticos não resolvidos.", "c": "Incorreta. Não há sinais de infecção bacteriana (glicose normal, líquido límpido).", "d": "Incorreta. Tempo muito longo para risco de neoplasia.", "e": "Incorreta. Lúpus não é o diagnóstico principal para este perfil clínico."}, "difficulty": "media", "tags": ["Pneumologia", "Fluxograma Diagnóstico", "VATS", "Oncologia"]}'::jsonb, 76, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Sobre o quilotórax, qual das seguintes manobras pode ajudar a visualizar a fístula do ducto torácico durante a cirurgia?", "options": {"a": "Ingestão pré-operatória de creme de leite ou azeite misturado com corante (ex: azul de metileno).", "b": "Hiperventilação mecânica com PEEP alto.", "c": "Injeção de contraste iodado endovenoso.", "d": "Uso de corticoides 24h antes.", "e": "Manobra de Valsalva mantida pelo anestesista."}, "answer": "a", "rationale": "Oferecer uma refeição rica em gorduras (creme de leite, sorvete) algumas horas antes da cirurgia aumenta a produção de linfa leitosa, facilitando a identificação do ponto de vazamento do ducto torácico no mediastino.", "option_rationales": {"a": "Correta. Técnica clássica de auxílio cirúrgico.", "b": "Incorreta. Ajuda a ver fístulas aéreas, não linfáticas.", "c": "Incorreta. O contraste circula no sangue, não no sistema linfático de forma imediata e visível.", "d": "Incorreta. Não auxilia na visualização.", "e": "Incorreta. Útil para ver escape aéreo."}, "difficulty": "media", "tags": ["Pneumologia", "Cirurgia Torácica", "Quilotórax", "Manejo Intraoperatório"]}'::jsonb, 77, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A ''Morte por empiema'' em pacientes idosos com pneumonia é muitas vezes acelerada por qual fator relacionado ao manejo do líquido pleural?", "options": {"a": "Drenagem excessivamente rápida de transudatos.", "b": "Atraso no reconhecimento e na drenagem de derrames parapneumônicos complicados.", "c": "Uso de antibióticos de espectro muito amplo.", "d": "Realização de fisioterapia motora precoce.", "e": "Suplementação de oxigênio em altos fluxos."}, "answer": "b", "rationale": "O atraso em identificar que um derrame de pneumonia tornou-se complicado (empiema) é uma causa maior de morbimortalidade. A formação de carapaças, sepse persistente e encarceramento pulmonar ocorrem rapidamente se a drenagem não for instituída oportunamente.", "option_rationales": {"a": "Incorreta. Transudatos raramente causam morte se drenados rápido (risco apenas de edema de reexpansão).", "b": "Correta. Tempo é pleura na infecção.", "c": "Incorreta. O erro costuma ser o espectro insuficiente.", "d": "Incorreta. Fisioterapia é benéfica.", "e": "Incorreta. Não é o fator de aceleração da morte por infecção pleural."}, "difficulty": "facil", "tags": ["Pneumologia", "Empiema", "Mortalidade", "Erros Médicos"]}'::jsonb, 78, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Qual a relação correta entre o lado do derrame e a patologia causal para as seguintes condições?", "options": {"a": "Derrame por Pancreatite: Frequentemente à Direita.", "b": "Derrame por Artrite Reumatoide: Frequentemente Bilateral.", "c": "Derrame por ICC: Frequentemente Unilateral Esquerdo.", "d": "Derrame por Ruptura de Ducto Torácico (abaixo de T5): Frequentemente à Direita.", "e": "Derrame por Tuberculose: Sempre Bilateral."}, "answer": "d", "rationale": "O ducto torácico cruza da direita para a esquerda ao nível de T4-T5. Lesões abaixo deste nível resultam em quilotórax à direita. Acima de T5, resultam em quilotórax à esquerda. A pancreatite costuma dar derrame à esquerda. ICC costuma ser bilateral ou à direita.", "option_rationales": {"a": "Incorreta. Pancreatite é predominantemente à esquerda.", "b": "Incorreta. Mais comumente unilateral (75-80% dos casos de AR são unilaterais).", "c": "Incorreta. ICC é bilateral ou direita (pela maior drenagem linfática à direita).", "d": "Correta. Anatomia clássica do ducto torácico.", "e": "Incorreta. TB é classicamente unilateral."}, "difficulty": "dificil", "tags": ["Pneumologia", "Anatomia", "Topografia dos Derrames"]}'::jsonb, 79, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente de 35 anos, com histórico de trauma esplênico grave (esplenectomia traumática) há 10 anos, apresenta-se agora com múltiplos pequenos nódulos pleurais incidentais em uma tomografia de tórax de rotina. Os nódulos são periféricos, bem delimitados e captam contraste. O paciente é assintomático. Qual a principal hipótese diagnóstica que evitaria uma biópsia desnecessária?", "options": {"a": "Mesotelioma maligno multicêntrico.", "b": "Metástases de tumor primário desconhecido.", "c": "Esplenose Torácica.", "d": "Sarcoidose nodular pleural.", "e": "Empiema crônico calcificado."}, "answer": "c", "rationale": "A esplenose torácica ocorre quando fragmentos de tecido esplênico são ''semeados'' na pleura após um trauma tóraco-abdominal com ruptura diafragmática e esplênica simultâneas. O tecido cresce e se vasculariza como múltiplos nódulos pleurais funcionantes. O diagnóstico pode ser confirmado por cintilografia com hemácias marcadas com tecnécio-99m (Tc-99m) ou mapeamento esplênico.", "option_rationales": {"a": "Incorreta. O asbesto e o tempo de latência não batem com o quadro.", "b": "Incorreta. No jovem assintomático com história de trauma prévio, a esplenose é mais provável.", "c": "Correta. Diagnóstico diferencial importante para nódulos pleurais pós-trauma.", "d": "Incorreta. Sarcoidose costuma ter linfonodomegalia hilar associada.", "e": "Incorreta. Nódulos de esplenose não são necessariamente calcificados."}, "difficulty": "dificil", "tags": ["Pneumologia", "Cirurgia de Trauma", "Esplenose Torácica", "Nódulo Pleural"]}'::jsonb, 80, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "No diagnóstico diferencial de derrames pleurais exsudativos, a medição do pH pleural é mandatória. Qual o cuidado técnico ESSENCIAL para garantir a validade do resultado na gasometria do líquido pleural?", "options": {"a": "Coletar o líquido em frasco de cultura aeróbia.", "b": "Garantir a ausência total de contato do líquido com o ar ambiente e coletar em seringa heparinizada de gasometria.", "c": "Adicionar soro fisiológico para diluir o excesso de proteínas.", "d": "Armazenar a amostra em temperatura ambiente por até 24 horas antes da análise.", "e": "Usar apenas tiras reagentes de urina (dipstick) para leitura imediata."}, "answer": "b", "rationale": "O pH do líquido pleural deve ser medido em um gasômetro, utilizando seringas heparinizadas (preferencialmente de vidro ou plástico hermético). O contato com o ar ambiente leva à perda de CO2, o que eleva artificialmente o pH, falseando o diagnóstico de empiema ou complicação.", "option_rationales": {"a": "Incorreta. O frasco de cultura não mantém a vedação gasosa necessária para o pH.", "b": "Correta. Protocolo padrão para análise de pH pleural.", "c": "Incorreta. A diluição altera o pH e a bioquímica.", "d": "Incorreta. A análise deve ser imediata ou a amostra deve ser mantida em gelo seco por curto período.", "e": "Incorreta. Tiras de urina são imprecisas para medir pH pleural e perdem a validade diagnóstica mínima necessária."}, "difficulty": "media", "tags": ["Pneumologia", "Procedimentos", "pH Pleural", "Laboratório"]}'::jsonb, 81, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Um paciente desenvolve derrame pleural volumoso. A toracentese revela líquido purulento com forte odor fétido. No Gram, observam-se múltiplas formas bacterianas (cocos e bastonetes), mas as culturas aeróbias tradicionais são negativas após 48h. Qual a provável etiologia?", "options": {"a": "Tuberculose Pleural mucoide.", "b": "Infecção por micro-organismos anaeróbios.", "c": "Nocardose pleural.", "d": "Líquido estéril pós-antibioticoterapia errática.", "e": "Hifas fúngicas mimetizando bactérias."}, "answer": "b", "rationale": "O odor fétido (putrefato) do líquido pleural é virtualmente patognomônico de infecção por bactérias anaeróbias. Como esses micro-organismos são de difícil crescimento em meios aeróbios ou ambientes sem transporte adequado, é comum que a cultura venha negativa se não houver meios específicos para anaeróbios.", "option_rationales": {"a": "Incorreta. TB não tem odor fétido.", "b": "Correta. Característica clássica do empiema por anaeróbios (frequentemente secundário a aspiração).", "c": "Incorreta. Nocardia é aeróbia e não produz o odor característico de digestão de tecidos dos anaeróbios.", "d": "Incorreta. Embora culturas negativas ocorram pós-atb, o odor aponta para a etiologia.", "e": "Incorreta. Fungos raramente produzem esse tipo de odor no espaço pleural."}, "difficulty": "media", "tags": ["Pneumologia", "Infectologia", "Anaeróbios", "Empiema"]}'::jsonb, 82, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A pleurodese com talco pode ser realizada via ''Talc Slurry'' (instilação de suspensão líquida pelo dreno) ou ''Talc Poudrage'' (insuflação de talco seco durante videotoracoscopia). Sobre a eficácia, qual a evidência trazida pelos grandes ensaios clínicos modernos?", "options": {"a": "O talco líquido (slurry) é infinitamente superior em todos os tipos de câncer.", "b": "O talco insuflado (poudrage) apresenta maior taxa de sucesso na sínfise pleural, especialmente em pacientes com câncer de mama ou pulmão.", "c": "Ambos têm eficácia idêntica, sendo o Slurry preferido por ser mais barato e menos invasivo.", "d": "O Slurry é mais seguro por não causar reação inflamatória sistêmica.", "e": "A pleurodese química não deve mais ser feita, sendo substituída por cateteres de demora em 100% dos casos."}, "answer": "b", "rationale": "Embora o Slurry seja eficaz e prático, grandes meta-análises sugerem que o ''Talc Poudrage'' (via VATS) garante uma distribuição mais uniforme do talco em toda a superfície pleural, resultando em taxas de sucesso ligeiramente superiores em grupos específicos e menor necessidade de reintervenção em oncologia.", "option_rationales": {"a": "Incorreta. Slurry é menos distribuído que o poudrage.", "b": "Correta. Superioridade na uniformidade da sínfise.", "c": "Incorreta. Existe uma tendência estatística de superioridade do Poudrage em estudos maiores.", "d": "Incorreta. Ambos podem causar SRIS se as partículas de talco forem pequenas demais (não graduadas).", "e": "Incorreta. A pleurodese ainda é padrão-ouro para muitos pacientes com pulmão reexpansível."}, "difficulty": "dificil", "tags": ["Pneumologia", "Oncologia", "Pleurodese", "Evidências"]}'::jsonb, 83, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Qual medicação anti-hipertensiva está associada ao Lupus Induzido por Drogas (Drug-Induced Lupus - DIL), cursando frequentemente com derrame pleural exsudativo e anticorpos anti-histona positivos no soro?", "options": {"a": "Enalapril.", "b": "Hidralazina.", "c": "Amlodipino.", "d": "Hidroclorotiazida.", "e": "Losartana."}, "answer": "b", "rationale": "A Hidralazina é uma das drogas mais clássicas associadas ao Lúpus Induzido por Drogas. Diferente do LES idiopático, o DIL costuma poupar o rim e o sistema nervoso central, manifestando-se principalmente por sintomas constitucionais, serosites (pericardite e pleurite) e artralgias. O marcador sorológico principal é o anticorpo anti-histona.", "option_rationales": {"a": "Incorreta. Não associada ao DIL.", "b": "Correta. Causa clássica de pleurite lúpica iatrogênica.", "c": "Incorreta. Pode dar edema de MMII, mas não lúpus.", "d": "Incorreta. Não associada.", "e": "Incorreta. Não associada."}, "difficulty": "media", "tags": ["Pneumologia", "Reumatologia", "Derrame Iatrogênico", "DIL"]}'::jsonb, 84, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Sobre o manejo do cateter pleural de demora (IPC), qual a complicação tardia específica desse dispositivo que pode ocorrer em até 2 a 5% dos pacientes com Mesotelioma Maligno?", "options": {"a": "Metástase no trajeto do cateter (Track metastasis).", "b": "Perfuração da veia cava superior.", "c": "Empiema bacteriano estéril.", "d": "Quilotórax secundário.", "e": "Necrose de pele por tração."}, "answer": "a", "rationale": "Células malignas (especialmente do mesotelioma e do adenocarcinoma de pulmão) podem ''semear'' o trajeto por onde o cateter pleural de demora passa na parede torácica. Isso resulta em nódulos tumorais subcutâneos dolorosos no local do cateter, conhecidos como ''track metastasis''. Muitas vezes exige radioterapia local profilática ou paliativa.", "option_rationales": {"a": "Correta. Fenômeno bem descrito em oncologia torácica.", "b": "Incorreta. Complicação de acesso venoso central, não de dreno pleural tunelizado.", "c": "Incorreta. O empiema purulento ocorre, mas não existe ''empiema estéril'' como diagnóstico de complicação do cateter.", "d": "Incorreta. Não há lesão do ducto torácico no trajeto subcutâneo do dreno.", "e": "Incorreta. Possível por erro de técnica, mas não é a complicação ''clássica'' tumoral descrita."}, "difficulty": "dificil", "tags": ["Pneumologia", "Oncologia", "Cateter Pleural", "Complicações"]}'::jsonb, 85, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A ''Pseudotumefação Pleural'' ou ''Tumor Evanescente'' no raio-X de tórax, associado à insuficiência cardíaca congestiva, localiza-se preferencialmente em qual estrutura anatômica?", "options": {"a": "Seio costofrênico posterior.", "b": "Espaço retroesternal.", "c": "Cisura horizontal (pequena cisura).", "d": "Ápice pulmonar.", "e": "Ângulo cardiofrênico esquerdo."}, "answer": "c", "rationale": "O tumor fantasma ou evanescente é o acúmulo de líquido loculado dentro de uma cisura pulmonar (mais comum na horizontal, à direita). Ao RX, a imagem biconvexa mimetiza uma massa sólida pulmonar, mas ''desaparece'' rapidamente após o tratamento com diuréticos.", "option_rationales": {"a": "Incorreta. Localização de derrames livres habituais.", "b": "Incorreta. Localização de massas mediastinais.", "c": "Correta. Localização anatômica clássica dessa variante radiológica.", "d": "Incorreta. Raro localização de derrames por gravidade.", "e": "Incorreta. Local de coxim gorduroso ou cistos pericárdicos."}, "difficulty": "media", "tags": ["Pneumologia", "Radiologia", "ICC", "Semiologia Radiológica"]}'::jsonb, 86, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A medição da adenosina deaminase (ADA) no líquido pleural tem excelente sensibilidade para Tuberculose. Entretanto, qual é a principal causa de FALSO-POSITIVO (ADA elevado sem TB) em pacientes idosos com derrame exsudativo?", "options": {"a": "Insuficiência Cardíaca.", "b": "Empiema e Artrite Reumatoide.", "c": "Derrame por Cirrose Hepática.", "d": "Urinotórax.", "e": "Atelectasia pós-cirúrgica."}, "answer": "b", "rationale": "O ADA é um marcador de ativação de linfócitos T. Assim, qualquer processo inflamatório muito intenso pode elevar o ADA. No empiema (especialmente se houver linfócitos ou lise celular), no linfoma e na Artrite Reumatoide, o ADA pode ultrapassar 40-70 U/L, gerando confusão com TB. No entanto, o empiema é neutrofílico, o que ajuda na diferenciação.", "option_rationales": {"a": "Incorreta. Transudatos têm ADA baixo.", "b": "Correta. Principais causas de falso-positivos elevados.", "c": "Incorreta. Transudatos têm ADA baixo.", "d": "Incorreta. Transudatos e sem inflamação aguda mediada por T.", "e": "Incorreta. ADA baixo."}, "difficulty": "media", "tags": ["Pneumologia", "Tuberculose", "Laboratório", "ADA"]}'::jsonb, 87, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Na análise do líquido pleural, um exsudato com predomínio de linfócitos e ADA elevado, mas que apresenta ABSÊNCIA total de células mesoteliais (< 5%), é altamente sugestivo de qual patologia?", "options": {"a": "Mesotelioma.", "b": "Tuberculose Pleural.", "c": "Carcinoma de Células Pequenas.", "d": "Pneumonia Atípica.", "e": "Lúpus Eritematoso Sistêmico."}, "answer": "b", "rationale": "A inflamação granulomatosa da pleura na tuberculose causa um intenso espessamento e recobrimento da pleura visceral por fibrina e colágeno, o que impede que as células mesoteliais (que revestem a pleura) descamem para o líquido. Por isso, a escassez ou ausência de mesoteliais é uma pista citológica clássica de TB pleural.", "option_rationales": {"a": "Incorreta. Mesoteliomas apresentam muitas células mesoteliais (as próprias células neoplásicas).", "b": "Correta. Dado clássico de citopatologia pleural.", "c": "Incorreta. Pode haver mesoteliais na carcinomatose secundária.", "d": "Incorreta. Não apresenta esse padrão inibitório.", "e": "Incorreta. No lúpus as mesoteliais podem ser normais ou até aumentadas e atípicas."}, "difficulty": "dificil", "tags": ["Pneumologia", "Tuberculose", "Citopatologia", "Mesoteliais"]}'::jsonb, 88, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "No diagnóstico de Embolia Pulmonar (TEP) por radiografia de tórax, um achado característico é uma opacidade em forma de cunha, com base voltada para a pleura, localizada na periferia do pulmão. Qual o nome deste sinal?", "options": {"a": "Sinal de Westermark.", "b": "Corcova de Hampton.", "c": "Sinal de Palla.", "d": "Sinal da Silhueta.", "e": "Linhas B de Kerley."}, "answer": "b", "rationale": "A ''Corcova de Hampton'' (Hampton''s Hump) representa um infarto pulmonar hemorrágico na periferia. É um achado radiográfico raro, mas clássico do TEP. O sinal de Westermark é a oligoemia focal distal à embolia.", "option_rationales": {"a": "Incorreta. Reflete área de menor vascularização, não consolidação em cunha.", "b": "Correta. Sinal clássico de infarto pulmonar periférico.", "c": "Incorreta. Reflete a dilatação da artéria pulmonar central por trombo.", "d": "Incorreta. Regra geral para localizar lesões intratorácicas.", "e": "Incorreta. Sinal de congestão venocapilar pulmonar e edema intersticial."}, "difficulty": "facil", "tags": ["Pneumologia", "TEP", "Radiologia", "Sinais Clássicos"]}'::jsonb, 89, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Atualmente, qual é o calibre de dreno pleural recomendado para o manejo inicial da maioria dos empiemas e derrames parapneumônicos, visando o conforto do paciente sem prejuízo na eficácia da drenagem?", "options": {"a": "Drenos de grande calibre (28-36 French).", "b": "Drenos de fino calibre (8-14 French), conhecidos como ''Pigtails''.", "c": "Sondas nasogástricas adaptadas.", "d": "Toracotomia aberta sem dreno.", "e": "Apenas agulhas de biópsia 14G."}, "answer": "b", "rationale": "Estudos randomizados recentes demonstraram que drenos de fino calibre (Pigtails, inseridos pela técnica de Seldinger) são tão eficazes quanto os drenos calibrosos para o manejo do empiema, com a vantagem de serem muito menos dolorosos para o paciente e apresentarem menores taxas de complicações de inserção.", "option_rationales": {"a": "Incorreta. Padrão antigo, agora reservado para hemotórax traumático com coágulos.", "b": "Correta. Tendência moderna de ''less is more'' no empiema.", "c": "Incorreta. Gambiarra não recomendada por diretrizes.", "d": "Incorreta. Procedimento de exceção para empiemas crônicos graves.", "e": "Incorreta. Insuficiente para drenagem contínua."}, "difficulty": "media", "tags": ["Pneumologia", "Terapêutica", "Drenagem Pleural", "Dispositivos"]}'::jsonb, 90, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A ''Asbestose'' associada ao ''Derrame Pleural Benigno do Asbesto'' (BAPE) é caracterizada pela presença de qual tipo de fibra de amianto que possui maior potencial carcinogênico e de irritação pleural devido à sua forma longa e rígida?", "options": {"a": "Crisotila (Amianto Branco).", "b": "Anfibólios (ex: Crocidolita ou Amianto Azul).", "c": "Gesso sintético.", "d": "Sílica cristalina.", "e": "Fibras de Carbono."}, "answer": "b", "rationale": "Embora a crisotila seja a mais utilizada comercialmente, os anfibólios (como a crocidolita e a amosita) são fibras retas, rígidas e finas que penetram profundamente no pulmão e alcançam a pleura com maior facilidade, apresentando maior potencial para causar mesotelioma e derrames benignos.", "option_rationales": {"a": "Incorreta. Menos persistente no tecido pleural que o anfibólio.", "b": "Correta. Tipo de amianto mais agressivo para a pleura.", "c": "Incorreta. Não causa patologia pleural clássica por fibras.", "d": "Incorreta. Causa silicose (parênquima e linfonodo), raramente derrame isolado.", "e": "Incorreta. Fibras modernas com baixo potencial de patogenicidade pleural comparada ao asbesto."}, "difficulty": "dificil", "tags": ["Pneumologia", "Doença Ocupacional", "Asbesto", "Toxicologia"]}'::jsonb, 91, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Em um paciente com Derrame Pleural Maligno por Adenocarcinoma de Pulmão, qual mutação driver, se presente no tecido ou no bloco de células do líquido pleural, permite o uso de terapia-alvo oral com alta taxa de controle do derrame?", "options": {"a": "KRAS G12C.", "b": "EGFR (Exon 19 deletion ou L858R).", "c": "P53 mutação nula.", "d": "BRAF V600E.", "e": "HER2/neu amplificação."}, "answer": "b", "rationale": "A presença de mutações ativadoras do EGFR permite o tratamento com inibidores de tirosina quinase (ex: Osimertinibe). Esses pacientes costumam responder muito bem, com rápida involução do derrame pleural maligno na maioria das vezes, por vezes evitando pleurodeses.", "option_rationales": {"a": "Incorreta. Menos responsiva a terapias isoladas de controle de serosite.", "b": "Correta. Alvo clássico e muito eficaz em oncologia pulmonar.", "c": "Incorreta. Mutação supressora tumoral sem terapia-alvo específica de controle rápido de derrame.", "d": "Incorreta. Mais rara no pulmão e menos associada a remissão completa de serosite volumosa.", "e": "Incorreta. Raro como driver isolado no pulmão."}, "difficulty": "media", "tags": ["Pneumologia", "Oncologia", "Terapia-Alvo", "EGFR"]}'::jsonb, 92, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A ''Pleurite Tuberculosa'' é classicamente descrita como uma resposta de hipersensibilidade retardada ao Mycobacterium tuberculosis. Por esse motivo, qual dos seguintes achados microbiológicos no líquido pleural é o MAIS COMUM nesse tipo de derrame?", "options": {"a": "Presença massiva de BAAR no sedimento (Gram de TB).", "b": "Cultura do líquido positiva em 90% dos casos.", "c": "Líquido pleural estéril (Cultura e BAAR negativos na maioria das vezes).", "d": "Presença de grânulos de enxofre.", "e": "Coloração de prata (Grocott) positiva."}, "answer": "c", "rationale": "Como a TB pleural é uma reação de hipersensibilidade mediada por linfócitos T a poucos antígenos bacilares no espaço pleural, a carga de bacilos no líquido é muito baixa. O BAAR é quase sempre negativo e a cultura do líquido é positiva em apenas 20-30% dos casos. O diagnóstico geralmente depende do ADA ou da biópsia pleural.", "option_rationales": {"a": "Incorreta. BAAR positivo em líquido é raríssimo na TB pleural isolada (sugerindo ruptura de cavidade).", "b": "Incorreta. Sensibilidade da cultura no líquido é baixa.", "c": "Correta. Padrão paucibacilar característico.", "d": "Incorreta. Clássico da Actinomicose.", "e": "Incorreta. Usado para fungos."}, "difficulty": "media", "tags": ["Pneumologia", "Tuberculose", "Microbiologia", "Fisiopatologia"]}'::jsonb, 93, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciated": "A embolia gasosa durante a toracentese é uma complicação rara, mas catastrófica. Qual deve ser a posição imediata do paciente se houver suspeita de embolia gasosa iatrogênica durante o procedimento?", "options": {"a": "Posição de Fowler (Sentado).", "b": "Decúbito Lateral Esquerdo e Trendelenburg (Posição de Durant).", "c": "Decúbito Dorsal com pernas elevadas.", "d": "Pronação imediata.", "e": "Posição Ortostática (Em pé)."}, "answer": "b", "rationale": "A posição de Durant (decúbito lateral esquerdo + Trendelenburg) visa manter a bolha de ar no ápice do ventrículo direito ou átrio direito, impedindo que ela entre na artéria pulmonar (no caso de embolia venosa) ou favorecendo a flutuação para longe da circulação cerebral (no caso de embolia arterial retrógrada via fencas).", "option_rationales": {"a": "Incorreta. Favorece a migração de ar para o cérebro.", "b": "Correta. Manobra clássica de emergência para embolia gasosa.", "c": "Incorreta. Não ajuda a aprisionar a bolha de ar no coração.", "d": "Incorreta. Inútil.", "e": "Incorreta. Perigoso."}, "difficulty": "dificil", "tags": ["Pneumologia", "Procedimentos", "Complicações", "Embolia Gasosa"]}'::jsonb, 94, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A ''Síndrome das Unhas Amarelas'' (Yellow Nail Syndrome) associa derrame pleural linfocítico a linfedema de membros inferiores e unhas distróficas amareladas. Qual é a etiologia básica aceita para esta síndrome?", "options": {"a": "Deposição crônica de ferro ungueal.", "b": "Disfunção congênita ou adquirida na drenagem linfática sistêmica.", "c": "Intoxicação por metais pesados (Cádmio).", "d": "Doença autoimune contra a queratina.", "e": "Infecção fúngica disseminada (onicomicose total)."}, "answer": "b", "rationale": "A síndrome decorre de uma hipoplasia ou obstrução funcional dos vasos linfáticos. O acúmulo de líquido linfático rico em proteínas na derme causa o linfedema e a alteração ungueal (crescimento lento e distrofia), além do derrame pleural por falha na absorção do líquido pelo sistema linfático pleural.", "option_rationales": {"a": "Incorreta. Sem relação.", "b": "Correta. Fisiopatologia central da síndrome.", "c": "Incorreta. Não existe nexo causal estabelecido.", "d": "Incorreta. Não é inflamatória autoimune por autoanticorpos.", "e": "Incorreta. As unhas são amarelas por estase linfática, não fungo primário (embora infecções secundárias possam ocorrer)."}, "difficulty": "media", "tags": ["Pneumologia", "Linfologia", "Derrame Pleural", "Síndromes"]}'::jsonb, 95, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "A atelectasia redonda (Round Atelectasis) é uma forma de colapso pulmonar periférico associada a doenças pleurais crônicas (ex: asbesto). Qual é o sinal radiográfico característico na tomografia computadorizada que confirma o diagnóstico?", "options": {"a": "Sinal do Brônquio aéreo no centro da massa.", "b": "Sinal da Cauda de Cometa (Comet Tail Sign) - vasos e brônquios curvando-se para dentro da massa.", "c": "Sinal do Halo (Halo Sign).", "d": "Broncograma de substituição.", "e": "Cavitação em ''meia lua''."}, "answer": "b", "rationale": "O ''Comet Tail Sign'' é a marca da atelectasia redonda. Representa a confluência de vasos e brônquios que são ''puxados'' e curvados em direção ao foco de parênquima colapsado por baixo da pleura espessada. É crucial para distinguir de câncer de pulmão.", "option_rationales": {"a": "Incorreta. Comum em pneumonia, não específico da atelectasia redonda.", "b": "Correta. Sinal clássico da atelectasia por asbesto.", "c": "Incorreta. Sugere aspergilose angioinvasiva.", "d": "Incorreta. Termo não utilizado.", "e": "Incorreta. Sugere aspergiloma (bola fúngica)."}, "difficulty": "media", "tags": ["Pneumologia", "Radiologia", "Asbesto", "Atelectasia Redonda"]}'::jsonb, 96, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Sobre o manejo do empiema pleural agudo, a videotoracoscopia (VATS) deve ser considerada precocemente em qual circunstância?", "options": {"a": "No primeiro dia de todo derrame parapneumônico simples.", "b": "Quando houver falha na drenagem tubular e antibioticoterapia (persistência de loculações radiológicas e febre) após 3-7 dias.", "c": "Apenas se o paciente estiver em choque séptico refratário.", "d": "Se o paciente for tabagista inveterado.", "e": "Substituindo o uso de antibióticos venosos."}, "answer": "b", "rationale": "A VATS precoce (nos primeiros 7 dias de infecção pleural persistente) é altamente eficaz para limpar loculações (debris de fibrina) e garantir a reexpansão pulmonar antes que a fibrina se transforme em tecido fibroso denso (fase de organização), o que exigiria uma cirurgia muito maior (toracotomia aberta).", "option_rationales": {"a": "Incorreta. Exagerado para casos simples que respondem a atb.", "b": "Correta. Janela de oportunidade para tratamento minimamente invasivo eficaz.", "c": "Incorreta. No choque a estabilização e drenagem rápida são prioridades.", "d": "Incorreta. Status tabágico não é indicação cirúrgica isolada.", "e": "Incorreta. Antibióticos são fundamentais."}, "difficulty": "media", "tags": ["Pneumologia", "Cirurgia Torácica", "Empiema", "Manejo"]}'::jsonb, 97, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "As placas pleurais são a manifestação radiológica mais comum da exposição ao asbesto. Qual a localização preferencial dessas placas?", "options": {"a": "Ápices pulmonares e pleura mediastinal.", "b": "Pleura parietal lateral, posterior e superfície diafragmática (poupando os ápices e os ângulos costofrênicos).", "c": "Cisuras interlobares exclusivamente.", "d": "Pleura visceral perihilar.", "e": "Traqueia e grandes brônquios."}, "answer": "b", "rationale": "As placas de asbesto são calcificações focais na pleura parietal. Elas têm predileção pelas zonas inferiores e médias das paredes torácicas lateral e posterior, além do diafragma. Elas classicamente poupam os ápices pulmonares e os recessos costofrênicos, o que ajuda a diferenciar de sequelas de TB ou empiema.", "option_rationales": {"a": "Incorreta. Ápice é mais comum para sequela de TB.", "b": "Correta. Distribuição anatômica característica do asbesto.", "c": "Incorreta. Cisuras podem ser acometidas, mas a parietal é o alvo principal.", "d": "Incorreta. Local de linfonodomegalia na sarcoidose.", "e": "Incorreta. Não acometem vias aéreas de grande calibre."}, "difficulty": "dificil", "tags": ["Pneumologia", "Doença Ocupacional", "Asbesto", "Radiologia"]}'::jsonb, 98, 'draft'), ('75b2c082-f706-4e24-aaa2-7ff578f23d66', '{"enunciado": "Paciente diagnosticado com Tuberculose Pleural (biópsia positiva). Inicia esquema RIPE. Após 15 dias de tratamento, apresenta aumento do volume do derrame pleural e febre leve, apesar de melhora do estado geral. Qual a interpretação correta?", "options": {"a": "Falência terapêutica por resistência às drogas de primeira linha.", "b": "Reação Paradoxal (efeito de reconstituição imune local).", "c": "Contaminação bacteriana secundária do derrame (Empiema pós-toracentese).", "d": "Desenvolvimento de Linfoma associado à TB.", "e": "Toxicidade hepática pela pirazinamida causando ascite translocada."}, "answer": "b", "rationale": "A ''Reação Paradoxal'' na TB pleural ocorre quando a carga bacilar cai pela medicação, mas a resposta inflamatória imune aumenta transitoriamente (pela exposição de antígenos bacilares), levando à piora radiológica ou do derrame. Se o paciente está clinicamente bem, a conduta é apenas observação e manutenção do RIPE.", "option_rationales": {"a": "Incorreta. Muito cedo para diagnosticar falha se houver melhora clínica.", "b": "Correta. Fenômeno autoimune reativo clássico pós-início de RIPE.", "c": "Incorreta. Possível, mas a reação paradoxal é mais comum se o dreno não estiver lá.", "d": "Incorreta. Improvável.", "e": "Incorreta. Toxicidade hepática causa dor e náuseas, não aumento isolado do derrame pleural em 15 dias sem ascite volumosa prévia."}, "difficulty": "media", "tags": ["Pneumologia", "Tuberculose", "Terapêutica", "Reação Paradoxal"]}'::jsonb, 99, 'draft');